import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';
import Login from './components/Login';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Login Handle කරන කොටස
  const handleLoginSubmit = async (username, password) => {
    try {
      const response = await fetch('http://localhost:8081/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      
      if (data.status === 'Success') {
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Backend Server එක Run වෙන්නේ නැහැ මචං!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentPage('Home');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      
      {/* 1️⃣ ඔයා හදපු වෙබ් සයිට් එකේ ප්‍රධාන Header එක (මේක වෙනස් වෙන්නේ නෑ) */}
      <Navbar 
         onLoginClick={() => setShowLoginModal(true)} 
         isLoggedIn={isLoggedIn} 
         setCurrentPage={setCurrentPage} 
         currentPage={currentPage}
      />

      {/* 2️⃣ මෙන්න මැද කොටස: Dashboard එක ආවම සයිඩ්බාර් එකයි ඇඩ්මින් පැනල් එකයි බෙදෙන්නේ මෙතනින් */}
      <main style={{ flex: 1, display: 'flex', flexDirection: 'row' }}>
        
        {/* සාමාන්‍ය පේජ් නම් මුළු පේජ් එකේම පෙනෙනවා */}
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
        {currentPage === 'Teachers' && <Teachers />}
        {currentPage === 'About' && <About />}
        
        {/* 🟢 ඩෑෂ්බෝඩ් එක ආපු ගමන්: වම් පැත්තේ සයිඩ්බාර් එක Header එකේ ඉඳන් Footer එකට වදින්නම හැදෙනවා */}
        {currentPage === 'Dashboard' && isLoggedIn && (
          <div style={{ display: 'flex', flex: 1, width: '100%' }}>
            
            {/* 🟩 කොළ පාට සයිඩ්බාර් එක (කෙලින්ම Footer එකේ නිල් පාට තීරුව ගාවටම වදිනවා) */}
            <div style={{ width: '260px', backgroundColor: '#15803d', color: '#ffffff', display: 'flex', flexDirection: 'column', padding: '20px 0' }}>
              <div style={{ padding: '0 25px 15px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
                <h2 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0, color: '#fff' }}>Admin Panel</h2>
              </div>
              <nav style={{ flex: 1, marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 10px' }}>
                <button style={{ width: '100%', padding: '12px 15px', backgroundColor: 'rgba(0,0,0,0.2)', color: '#fff', border: 'none', borderRadius: '8px', textAlign: 'left', cursor: 'pointer', fontWeight: 'bold' }}>📊 Overview</button>
                <button style={{ width: '100%', padding: '12px 15px', backgroundColor: 'transparent', color: '#fff', border: 'none', borderRadius: '8px', textAlign: 'left', cursor: 'pointer' }}>👨‍🎓 Students</button>
                <button style={{ width: '100%', padding: '12px 15px', backgroundColor: 'transparent', color: '#fff', border: 'none', borderRadius: '8px', textAlign: 'left', cursor: 'pointer' }}>🏫 Teachers & Classes</button>
              </nav>
            </div>

            {/* ⬜ දකුණු පැත්තේ ප්‍රධාන Dashboard Content එක (Graph, Table ඔක්කොම තියෙන තැන) */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: '#f8fafc' }}>
              
              {/* 👤 Header එකට කෙලින්ම යටින් දකුණු පැත්තේ එන Welcome Admin සහ Logout තීරුව */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px 30px', borderBottom: '1px solid #e2e8f0', backgroundColor: '#ffffff' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <div style={{ width: '32px', height: '32px', backgroundColor: '#e2e8f0', borderRadius: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>👤</div>
                  <span style={{ fontWeight: '600', color: '#1e293b', fontSize: '14px' }}>Welcome, admin 👋</span>
                </div>
                <button onClick={handleLogout} style={{ backgroundColor: '#dc2626', color: '#ffffff', border: 'none', padding: '10px 18px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>
                  🚪 Logout
                </button>
              </div>

              {/* 📊 Graph, Tables සහ බටන් 3 ලෝඩ් වෙන ප්‍රධාන Dashboard Container එක */}
              <div style={{ padding: '30px', flex: 1, overflowY: 'auto' }}>
                <LmsDashboard />
              </div>

            </div>

          </div>
        )}
      </main>

      {/* 3️⃣ ඔයාගේ මුල් වෙබ් සයිට් එකේ Footer එක (මේක හැමදාම යටින්ම තියෙනවා) */}
      <Footer />

      {showLoginModal && (
        <Login setShowLoginModal={setShowLoginModal} handleLoginSubmit={handleLoginSubmit} />
      )}
    </div>
  );
}
